    deleteEntryLogically: {
        parameters: {
            query: {
                /** @description Justificativa do cancelamento (mínimo 5, máximo 500 caracteres) */
                reason: string;
            };
            header?: {
                /** @description ETag do lançamento (opcional); se não corresponder à versão atual, responde 412 */
                "If-Match"?: string;
            };
            path: {
                /** @description UUID do lançamento financeiro */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Lançamento cancelado (ou já estava cancelado) */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Justificativa com mais de 500 caracteres */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetail"];
                };
            };
            /** @description Acesso negado (exclusivo para ADMIN) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetail"];
                };
            };
            /** @description Lançamento financeiro não encontrado */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetail"];
                };
            };
            /** @description If-Match informado não corresponde à versão atual do lançamento */
            412: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetail"];
                };
            };
            /** @description Justificativa com menos de 5 caracteres, lançamento liquidado (CANNOT_CANCEL_SETTLED_ENTRY) ou com filho residual ativo (ENTRY_HAS_ACTIVE_CHILDREN) */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetail"];
                };
            };
        };
    };
